CREATE TABLE editor_assets_general(asset_id TEXT PRIMARY KEY CHECK(length(asset_id)=36),attempt_id TEXT NOT NULL UNIQUE CHECK(length(attempt_id)=64),document_id TEXT NOT NULL REFERENCES editor_documents(document_id),generation TEXT NOT NULL CHECK(length(generation)=64),object_key TEXT NOT NULL UNIQUE CHECK(length(object_key)=80),status TEXT NOT NULL CHECK(status IN ('pending','ready','terminal')),reserved_bytes INTEGER NOT NULL CHECK(reserved_bytes BETWEEN 1 AND 10485760),byte_size INTEGER NOT NULL CHECK(byte_size BETWEEN 0 AND reserved_bytes),media_type TEXT NOT NULL,media_kind TEXT NOT NULL DEFAULT 'image',safe_name TEXT NOT NULL CHECK(length(safe_name) BETWEEN 1 AND 128),sha256 TEXT NOT NULL CHECK(length(sha256) IN (0,64)),lease_until INTEGER NOT NULL CHECK(lease_until BETWEEN 0 AND 9007199254740991),next_probe_at INTEGER NOT NULL CHECK(next_probe_at BETWEEN 0 AND 9007199254740991),claim_token TEXT NOT NULL CHECK(length(claim_token) IN (0,64)),created_at INTEGER NOT NULL CHECK(created_at BETWEEN 1 AND 9007199254740991),CHECK(status<>'ready' OR (byte_size>0 AND length(sha256)=64)),CHECK(length(media_type) BETWEEN 3 AND 127),CHECK(media_kind IN ('image','audio','video','file')),CHECK(media_kind<>'image' OR media_type IN ('image/png','image/jpeg','image/webp')),CHECK(media_kind<>'audio' OR media_type IN ('audio/wav','audio/mpeg','audio/ogg')),CHECK(media_kind<>'video' OR media_type IN ('video/webm','video/mp4')));
INSERT INTO editor_assets_general(asset_id,attempt_id,document_id,generation,object_key,status,reserved_bytes,byte_size,media_type,safe_name,sha256,lease_until,next_probe_at,claim_token,created_at,media_kind) SELECT asset_id,attempt_id,document_id,generation,object_key,status,reserved_bytes,byte_size,media_type,safe_name,sha256,lease_until,next_probe_at,claim_token,created_at,'image' FROM editor_assets;
DROP TRIGGER editor_assets_document_fence;
DROP TABLE editor_assets;
ALTER TABLE editor_assets_general RENAME TO editor_assets;
CREATE INDEX editor_assets_document ON editor_assets(document_id,status);
CREATE INDEX editor_assets_probe ON editor_assets(status,next_probe_at,lease_until);
CREATE TRIGGER editor_assets_document_fence AFTER UPDATE OF generation,deleted ON editor_documents WHEN NEW.deleted=1 OR NEW.generation<>OLD.generation BEGIN UPDATE editor_assets SET status='terminal',next_probe_at=0 WHERE document_id=NEW.document_id; END;
